window.docContents[129].resolve({"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Examples-of-Lie-algebras-_LPAR_continued_RPAR____-Lie-subalgebras/#Chapter2___Example2___9___2_continued":{"contents":"(5) Any subspace \\mathfrak{a} of a Lie algebra \\mathfrak{g} which is closed under the commutator map [\\ ,\\ ], i.e., such that [a, b] \\in \\mathfrak{a} if a, b \\in \\mathfrak{a}. Such a subspace is called a Lie subalgebra of \\mathfrak{g}.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.9. Lie algebras\tExamples of Lie algebras (continued): Lie subalgebras","header":"Examples of Lie algebras (continued): Lie subalgebras","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Examples-of-Lie-algebras-_LPAR_continued_RPAR____-Lie-subalgebras/#Chapter2___Example2___9___2_continued"},"/5___-Representations-of-finite-groups___-Further-results/5___4___-Burnside___s-theorem/Group-with-conjugacy-class-of-size-p___k-is-not-simple/#Chapter5___Theorem5___4___6":{"contents":"Theorem 5.4.6. Let G be a finite group, and let C be a conjugacy class in G of size p^k where p is a prime and k > 0. Then G has a proper nontrivial normal subgroup (i.e., G is not simple).\n\nProof. Choose an element g \\in C. Since g \\neq e, by orthogonality of columns of the character table,\n\n(5.4.1) \\qquad \\sum_{V \\in \\operatorname{Irr} G} \\dim V \\chi_V(g) = 0.\n\nWe can divide \\operatorname{Irr} G into three parts:\n\n(1) the trivial representation,\n\n(2) D, the set of irreducible representations whose dimension is divisible by p, and\n\n(3) N, the set of nontrivial irreducible representations whose dimension is not divisible by p.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.4. Burnside's theorem\tGroup with conjugacy class of size p^k is not simple","header":"Group with conjugacy class of size p^k is not simple","id":"/5___-Representations-of-finite-groups___-Further-results/5___4___-Burnside___s-theorem/Group-with-conjugacy-class-of-size-p___k-is-not-simple/#Chapter5___Theorem5___4___6"},"/7___-Introduction-to-categories/7___3___-Morphisms-of-functors/Section-7___3___-Morphisms-of-functors/#Chapter7___Introduction_7___3___heading-1":{"contents":"One of the important features of functors between categories which distinguishes them from usual maps or functions is that the functors between two given categories themselves form a category; i.e., one can define a nontrivial notion of a morphism between two functors.\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.3. Morphisms of functors\tSection 7.3: Morphisms of functors","header":"7.3. Morphisms of functors","id":"/7___-Introduction-to-categories/7___3___-Morphisms-of-functors/Section-7___3___-Morphisms-of-functors/#Chapter7___Introduction_7___3___heading-1"},"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/#chapter-07___section-7-4":{"contents":"\n\n\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories","header":"7.4. Equivalence of categories","id":"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/#chapter-07___section-7-4"},"/8___-Homological-algebra/8___1___-Projective-and-injective-modules/Definition-8___1___8-___-Projective-and-injective-objects-in-abelian-categories/#Chapter8___Definition8___1___8":{"contents":"Definition 8.1.8. A projective object in an abelian category \\mathcal{C} is an object P such that the functor \\operatorname{Hom}_\\mathcal{C}(P, ?) is exact.\n\nAn injective object in an abelian category \\mathcal{C} is an object I such that the functor \\operatorname{Hom}_\\mathcal{C}(?, I) is exact.\n\n\n\n","context":"Introduction to Representation Theory\t8. Homological algebra\t8.1. Projective and injective modules\tDefinition 8.1.8 — Projective and injective objects in abelian categories","header":"Definition 8.1.8 — Projective and injective objects in abelian categories","id":"/8___-Homological-algebra/8___1___-Projective-and-injective-modules/Definition-8___1___8-___-Projective-and-injective-objects-in-abelian-categories/#Chapter8___Definition8___1___8"}});
